    _entry("Last PWM: {value}. The optional daemon reads this same saved curve from config.json.", "Último PWM: {value}. El daemon opcional usa esta misma curva guardada en config.json.", "Último PWM: {value}. O daemon opcional usa esta mesma curva salva em config.json.", "Последний PWM: {value}. Дополнительная служба использует эту же сохранённую кривую из config.json.", "Останній PWM: {value}. Додаткова служба використовує цю саму збережену криву з config.json.", "Letztes PWM: {value}. Der optionale Daemon verwendet dieselbe in config.json gespeicherte Kurve."),
    _entry("Staged duty: {value}% · raw PWM {raw}/255. No write occurs until confirmed.", "Valor preparado: {value}% · PWM bruto {raw}/255. No se escribirá nada hasta que confirmes.", "Valor preparado: {value}% · PWM bruto {raw}/255. Nada será gravado antes da confirmação.", "Подготовленное значение: {value}% · PWM {raw}/255. Запись выполняется только после подтверждения.", "Підготовлене значення: {value}% · PWM {raw}/255. Запис виконується лише після підтвердження.", "Vorgemerktes Tastverhältnis: {value}% · PWM-Rohwert {raw}/255. Erst nach Bestätigung wird geschrieben."),
